double LWMA(int shift, int period, const double &price[])
{
   double result = 0.0;
   double weightSum = 0.0;

   for (int i = shift; i < shift + period; i++)
   {
      result += price[i] * (period - (i - shift));
      weightSum += period - (i - shift);
   }
   result /= weightSum;

   return result;
