                // 设置圆形属性
                ellipse.Width = circle[2] * 2;
                ellipse.Height = circle[2] * 2;
                Canvas.SetLeft(ellipse, circle[0] - circle[2]);
                Canvas.SetTop(ellipse, circle[1] - circle[2]);
                ellipse.Stroke = Brushes.Black;
                ellipse.Fill = Brushes.Transparent;

                // 将圆形加入canvas
                canvas.Children.Add(ellipse);
            }

            // 创建折线（polylines）的画布元素
            foreach (var points in data.shape.polylines)
            {
                var polyline = new Polyline();

                // 将折线的点坐标添加到PointCollection中
                var pointCollection = new PointCollection();
                foreach (var point in points)
                {
                    pointCollection.Add(new Point(point[0], point[1]));
                }

                // 设置折线属性
                polyline.Points = pointCollection;
                polyline.Stroke = Brushes.Black;

                // 将折线加入canvas
                canvas.Children.Add(polyline);
            }
        }

